messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Red vs Blue Car Race</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background-color: #87CEEB; /* Sky blue fallback */
        }
        canvas {
            display: block;
        }
        #info {
            position: absolute;
            top: 20px;
            width: 100%;
            text-align: center;
            font-family: sans-serif;
            font-size: 24px;
            font-weight: bold;
            color: white;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="info">The Race</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 200;
        const RACE_DURATION = 6000; // ms per loop
        const RESET_DELAY = 2000; // ms pause at end

        // --- Setup Scene ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky color
        scene.fog = new THREE.Fog(0x87CEEB, 50, 300);

        const camera = new THREE.Perspective(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(-20, 15, 40);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(-50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 500;
        dirLight.shadow.camera.left = -100;
        dirLight.shadow.camera.right = 100;
        dirLight.shadow.camera.top = 100;
        dirLight.shadow.camera.bottom = -100;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(1000, 1000);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a9d3a });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.1;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track
        const trackGeo = new THREE.PlaneGeometry(1000, 40);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0;
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line
        const finishLineGeo = new THREE.PlaneGeometry(100, 40);
        // Create a simple checkerboard texture using canvas
        const canvas = document.createElement('canvas');
        canvas.width = 64;
        canvas.height = 64;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = 'white';
        ctx.fillRect(0,0,64,64);
        ctx.fillStyle = 'black';
        ctx.fillRect(0,0,32,32);
        ctx.fillRect(32,32,32,32);
        const texture = new THREE.CanvasTexture(canvas);
        texture.wrapS = THREE.RepeatWrapping;
        texture.wrapT = THREE.RepeatWrapping;
        texture.repeat.set(10, 4);

        const finishLineMat = new THREE.MeshStandardMaterial({ map: texture });
        const finishLine = new THREE.Mesh(finishLineGeo, finishLineMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(TRACK_LENGTH, 0.1, 0);
        finishLine.receiveShadow = true;
        scene.add(finishLine);

        // Finish Line Posts
        const postGeo = new THREE.BoxGeometry(2, 15, 2);
        const postMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const post1 = new THREE.Mesh(postGeo, postMat);
        post1.position.set(TRACK_LENGTH, 7.5, 20);
        post1.castShadow = true;
        scene.add(post1);
        const post2 = new THREE.Mesh(postGeo, postMat);
        post2.position.set(TRACK_LENGTH, 7.5, -20);
        post2.castShadow = true;
        scene.add(post2);

        // Banner
        const bannerGeo = new THREE.BoxGeometry(40, 5, 1);
        const bannerMat = new THREE.MeshStandardMaterial({ color: 0xffd700 });
        const banner = new THREE.Mesh(bannerGeo, bannerMat);
        banner.position.set(TRACK_LENGTH, 12, 0);
        banner.castShadow = true;
        scene.add(banner);

        // --- Car Creation Helper ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(2, 1, 4);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 1;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.8, 0.8, 2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = 1.8;
            cabin.position.z = -0.5;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                { x: -1, y: 0.6, z: 1.2 },
                { x: 1, y: 0.6, z: 1.2 },
                { x: -1, y: 0.6, z: -1.2 },
                { x: 1, y: 0.6, z: -1.2 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, pos.y, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Spoiler
            const spoilerGeo = new THREE.BoxGeometry(2, 0.2, 0.8);
            const spoiler = new THREE.Mesh(spoilerGeo, chassisMat);
            spoiler.position.set(0, 2, -1.5);
            carGroup.add(spoiler);

            const spoilerLegsGeo = new THREE.BoxGeometry(0.2, 0.5, 0.2);
            const leg1 = new THREE.Mesh(spoilerLegsGeo, chassisMat);
            leg1.position.set(-0.7, 1.75, -1.5);
            carGroup.add(leg1);
            const leg2 = new THREE.Mesh(spoilerLegsGeo, chassisMat);
            leg2.position.set(0.7, 1.75, -1.5);
            carGroup.add(leg2);

            return carGroup;
        }

        const redCar = createCar(0xFF0000);
        const blueCar = createCar(0x0000FF);

        // Initial positions
        redCar.position.set(-50, 0, 5); // Right lane
        blueCar.position.set(-50, 0, -5); // Left lane
        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---
        let raceStartTime = performance.now();
        let isRacing = true;

        function animate() {
            requestAnimationFrame(animate);

            const now = performance.now();
            let time = now - raceStartTime;

            // Reset Logic
            if (time > RACE_DURATION + RESET_DELAY) {
                raceStartTime = now;
                time = 0;
            }

            // Calculate Progress (0 to 1)
            let progress = 0;
            if (time <= RACE_DURATION) {
                progress = time / RACE_DURATION;
            } else {
                progress = 1; // Keep at finish line during delay
            }

            // --- Car Movement Logic ---

            // Blue Car: Leads early, slows down slightly, then finishes
            // Simple easing: Fast start, steady middle, slight slow end
            let bluePos = -50 + (TRACK_LENGTH + 100) * progress;
            // Add some visual "wobble" or speed variation based on sine wave
            let blueSpeedMod = Math.sin(progress * Math.PI * 4) * 2;
            blueCar.position.x = bluePos + blueSpeedMod;
            blueCar.position.z = -5; // Keep in lane

            // Red Car: Starts slower, accelerates hard, overtakes
            // Custom easing: Slow start, exponential acceleration
            // Using a power curve: t^3 starts slow, ends fast
            let redBaseProgress = Math.pow(progress, 2.5);
            let redPos = -50 + (TRACK_LENGTH + 100) * redBaseProgress;
            // Add some visual "wobble"
            let redSpeedMod = Math.sin(progress * Math.PI * 5) * 1.5;
            redCar.position.x = redPos + redSpeedMod;
            redCar.position.z = 5; // Keep in lane

            // --- Camera Logic ---
            // Camera follows the "pack"
            const leadCar = blueCar.position.x > redCar.position.x ? blueCar : redCar;
            const trailingCar = blueCar.position.x > redCar.position.x ? redCar : blueCar;

            // Center camera between cars, slightly behind
            const camTargetX = (leadCar.position.x + trailingCar.position.x) / 2 - 20;
            const camTargetY = 15;
            const camTargetZ = 35;

            // Smooth camera movement
            camera.position.x += (camTargetX - camera.position.x) * 0.1;
            camera.position.y += (camTargetY - camera.position.y) * 0.1;
            camera.position.z += (camTargetZ - camera.position.z) * 0.1;

            // Look slightly ahead of the cars
            const lookAheadX = (leadCar.position.x + trailingCar.position.x) / 2 + 20;
            camera.lookAt(lookAheadX, 0, 0);

            // --- Update Info Text ---
            const info = document.getElementById('info');
            if (progress < 0.95) {
                if (redCar.position.x > blueCar.position.x) {
                    info.innerText = "RED IS LEADING!";
                    info.style.color = "#FF5555";
                } else {
                    info.innerText = "BLUE IS LEADING!";
                    info.style.color = "#5555FF";
                }
            } else {
                // Determine winner
                if (redCar.position.x > blueCar.position.x) {
                    info.innerText = "RED WINS!";
                    info.style.color = "#FF5555";
                } else {
                    info.innerText = "BLUE WINS!";
                    info.style.color = "#5555FF";
                }
            }

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start Loop
        animate();

    </script>
</body>
</html>
```
